package org.eclipse.rdf4j.query.algebra.evaluation.optimizer;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.Dataset;
import org.eclipse.rdf4j.query.algebra.BindingSetAssignment;
import org.eclipse.rdf4j.query.algebra.Service;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryOptimizer;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.query.algebra.helpers.QueryAlgebraBindingAnalysis;

/**
 * Optimizes a query model by inlining {@link BindingSetAssignment} values where possible.
 *
 * @author Jeen Broekstra
 */
public class BindingSetAssignmentInlinerOptimizer implements QueryOptimizer {

	@Override
	public void optimize(TupleExpr tupleExpr, Dataset dataset, BindingSet bindings) {
		QueryAlgebraBindingAnalysis bindingAnalysis = QueryAlgebraBindingAnalysis.withBindingValues(tupleExpr,
				bindings);
		BindingSetAssignmentVisitor visitor = new BindingSetAssignmentVisitor(bindingAnalysis, tupleExpr);
		tupleExpr.visit(visitor);
	}

	private static class BindingSetAssignmentVisitor extends AbstractQueryModelVisitor<RuntimeException> {

		private final QueryAlgebraBindingAnalysis bindingAnalysis;
		private final TupleExpr root;

		private BindingSetAssignmentVisitor(QueryAlgebraBindingAnalysis bindingAnalysis, TupleExpr root) {
			this.bindingAnalysis = bindingAnalysis;
			this.root = root;
		}

		@Override
		public void meet(Service node) throws RuntimeException {
			// do not inject bindings inside service clauses
		}

		@Override
		public void meet(Var var) {
			if (var.getName() == null || var.hasValue() || var.isConstant()) {
				return;
			}
			QueryAlgebraBindingAnalysis.ReadOnlyContext input = bindingAnalysis.contextAt(var);
			if (!input.guaranteedNames().contains(var.getName())) {
				return;
			}
			Value replacementValue = input.fixedValues().get(var.getName());
			if (replacementValue != null) {
				var.replaceWith(Var.of(var.getName(), replacementValue, var.isAnonymous(), var.isConstant()));
				bindingAnalysis.invalidate(root);
			}
		}
	}
}
